"""Generate RULES.md from hyniqe_shield/rules.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main():
    d = json.loads((ROOT / "hyniqe_shield" / "rules.json").read_text(encoding="utf-8"))
    out = ["# Hyniqe Shield detection rules", "",
           f"Rules version {d['version']}. Each rule is mapped to the "
           "[OWASP Top 10 for Agentic Applications 2026](https://genai.owasp.org/resource/owasp-top-10-for-agentic-applications-for-2026/).",
           "", "This file is generated by `scripts/build_docs.py`; edit `hyniqe_shield/rules.json` instead.", "",
           "## OWASP categories", ""]
    out += [f"- **{k}** {v}" for k, v in d["owasp"].items()]
    out += ["", "## Pattern rules", "", "| ID | Severity | OWASP | Rule | Applies to |", "|---|---|---|---|---|"]
    for r in d["rules"]:
        out.append(f"| {r['id']} | {r['severity']} | {', '.join(r['owasp'])} | {r['title']} | {', '.join(r['applies_to'])} |")
    out += ["", "## Structural rules", "", "These understand the file's structure (MCP configs, n8n workflows, skill "
            "front matter, hidden Unicode) or combine findings.", "",
            "| ID | Severity | OWASP | Rule |", "|---|---|---|---|"]
    for k, r in d["structural_rules"].items():
        out.append(f"| {k} | {r['severity']} | {', '.join(r['owasp'])} | {r['title']} |")
    out += ["", "## What each rule means", ""]
    for r in d["rules"]:
        out.append(f"### {r['id']} {r['title']}\n\n{r['explain']}\n\n**Fix:** {r['fix']}\n")
    for k, r in d["structural_rules"].items():
        out.append(f"### {k} {r['title']}\n\n{r['explain']}\n\n**Fix:** {r['fix']}\n")
    out += ["## Scoring", "",
            "Each rule adds its severity weight once per scan (critical 40, high 20, medium 8, low 2, info 0); "
            "repeats add a quarter of the weight, up to four more times. The score is capped at 100.", "",
            "- **Dangerous**: any critical finding, or two or more different high-severity rules",
            "- **Caution**: any high finding, or a score of 10 or more",
            "- **No known risks found**: everything else. This is not a guarantee of safety.", ""]
    (ROOT / "RULES.md").write_text("\n".join(out), encoding="utf-8")
    print("wrote RULES.md")


if __name__ == "__main__":
    main()
